import{_ as r,C as o,c as l,o as s,ag as u,j as e,G as n,a}from"./chunks/framework.Bw-5EFTY.js";const w=JSON.parse('{"title":"SureCart Integration with FluentAffiliate","description":"","frontmatter":{},"headers":[],"relativePath":"guide/integrations/surecart-integration-with-fluentaffiliate.md","filePath":"guide/integrations/surecart-integration-with-fluentaffiliate.md","lastUpdated":1755603747000}'),f={name:"guide/integrations/surecart-integration-with-fluentaffiliate.md"};function g(c,t,d,p,h,m){const i=o("ZoomableImage");return s(),l("div",null,[t[0]||(t[0]=u('<h1 id="surecart-integration-with-fluentaffiliate" tabindex="-1">SureCart Integration with FluentAffiliate <a class="header-anchor" href="#surecart-integration-with-fluentaffiliate" aria-label="Permalink to &quot;SureCart Integration with FluentAffiliate&quot;">​</a></h1><p>SureCart is a modern e-commerce platform for WordPress, built to make selling products and services online easy and efficient. If you&#39;re using SureCart and want to boost your sales, integrating with FluentAffiliate allows you to launch a powerful affiliate program and effortlessly manage commissions for every referral.</p><p>This guide will walk you through the simple steps to connect SureCart with FluentAffiliate.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Surecart is a pro feature of FluentAffiliate. To use it, you need FluentAffiliate Pro.</p><p>To get started, you first need to install and activate the SureCart plugin on your WordPress website.</p></div><h2 id="enable-surecart-in-fluentaffiliate" tabindex="-1">Enable SureCart in FluentAffiliate <a class="header-anchor" href="#enable-surecart-in-fluentaffiliate" aria-label="Permalink to &quot;Enable SureCart in FluentAffiliate&quot;">​</a></h2><p>Activating the connection between SureCart and FluentAffiliate is as simple as flipping a switch.</p><ol><li>From your WordPress Dashboard, navigate to the <strong>FluentAffiliate Dashboard</strong>.</li><li>Click on the <strong>Settings</strong> tab in the top menu.</li><li>On the left sidebar, find and click on <strong>Integration Settings</strong>.</li><li>You will see a list of different integration options. Find <strong>SureCart</strong> in this list and click the <strong>toggle</strong> button to enable the integration.</li></ol><p>That&#39;s it! Unlike some other integrations, there are no extra settings to configure. Once the toggle is active, your SureCart store is connected to <strong>FluentAffiliate</strong>, and it&#39;s ready to start tracking affiliate referrals.</p>',8)),e("p",null,[n(i,{src:"/guide/public/images/integrations/surecart/integration-setup-options.webp",alt:"Integration Settings"})]),t[1]||(t[1]=e("h2",{id:"generate-an-affiliate-link",tabindex:"-1"},[a("Generate an Affiliate Link "),e("a",{class:"header-anchor",href:"#generate-an-affiliate-link","aria-label":'Permalink to "Generate an Affiliate Link"'},"​")],-1)),t[2]||(t[2]=e("p",null,[a("Once you've finished setting up your "),e("strong",null,"Surecart"),a(" product settings, it's time to generate your "),e("a",{href:"/guide/affiliate-portal/generating-affiliate-links"},"affiliate link"),a(".")],-1)),t[3]||(t[3]=e("p",null,"When a customer clicks the link and completes a purchase, a commission will be automatically tracked and awarded to the affiliate based on your global commission settings.",-1)),e("p",null,[n(i,{src:"/guide/public/images/integrations/surecart/referral-overview.webp",alt:"Referral"})]),t[4]||(t[4]=e("p",null,"And that's it! This is how easily you can connect SureCart with FluentAffiliate and start earning commissions by promoting SureCart products.",-1))])}const S=r(f,[["render",g]]);export{w as __pageData,S as default};
